# Build directories
export CMUL_BUILD_DIR="$CMUL_DIR/build"
export CMUL_SIM_BUILD_DIR="$CMUL_BUILD_DIR/simulation"
export CMUL_SYNTH_BUILD_DIR="$CMUL_BUILD_DIR/synthesis"
export CMUL_IMPL_BUILD_DIR="$CMUL_BUILD_DIR/implementation"

# Source directories
export CMUL_CPP_DIR="$CMUL_DIR/cpp"
export CMUL_FLIST_DIR="$CMUL_DIR/flist"
export CMUL_RTL_DIR="$CMUL_DIR/rtl"
export CMUL_TB_DIR="$CMUL_DIR/testbench"
export CMUL_SYNTH_DIR="$CMUL_DIR/synthesis"
export CMUL_IMPL_DIR="$CMUL_DIR/implementation"

# C++ model files
export CMUL_CPP_HPP="$CMUL_CPP_DIR/cmul.hpp"
export CMUL_CPP_CPP="$CMUL_CPP_DIR/cmul.cpp"

# RTL files
export CMUL_V="$CMUL_RTL_DIR/cmul.v"

# Testbench files
export CMUL_TB_CPP="$CMUL_TB_DIR/cmul_tb.cpp"
export CMUL_TB_HPP="$CMUL_TB_DIR/cmul_tb.hpp"
export CMUL_TB_SV="$CMUL_TB_DIR/cmul_tb.sv"
