# Backward-compatible alias for simulation regression JSON
export CMUL_REGRESSION_JSON="$CMUL_TB_REGRESSION_JSON"

# Synthesis files
export CMUL_SYNTH_WRAPPER_V="$CMUL_SYNTH_DIR/cmul_wrapper_synth.v"
