# Flists
export CMUL_TB_FLIST="$CMUL_FLIST_DIR/cmul_tb.flist"
export CMUL_SYNTH_FLIST="$CMUL_FLIST_DIR/cmul_synth.flist"
export CMUL_IMPL_FLIST="$CMUL_FLIST_DIR/cmul_impl.flist"

